from taf.gnb.oam.coam.admin.exceptions import raise_value_error


class CplaneDuTrace(object):
    def __init__(self, source_ip, dscp, destination_ip, destination_port):
        self.source_ip = source_ip
        self.dscp = self.validate_param('dscp', dscp, 0 <= dscp <= 63)
        self.destination_ip = destination_ip
        self.destination_port = self.validate_param('destinationPort',
                                                    destination_port,
                                                    1024 <= destination_port <= 65535)

    def as_dict(self):
        attributes = {
            "configurationParameters": {
                "sourceIp": self.source_ip,
                "dscp": self.dscp,
                "destinationIp": self.destination_ip,
                "destinationPort": self.destination_port
            }
        }
        return attributes

    @staticmethod
    def validate_param(param, value, valid):
        return value if valid else raise_value_error(
            param=param,
            value=str(value),
            subpage="tutorial-startCPlaneDUTrace.html")
